#Requires -Version 5.1
# fix-dashboard-sinasignar-id.ps1
# Bug: Luis y Tarsicio aparecian como "sin asignar" aunque estaban asignados.
# Causa: la comparacion usaba el NOMBRE del recurso (assignedNames) en lugar
# del ID. Si habia cualquier diferencia de formato (tildes, espacios, mayusculas)
# el nombre no coincdia y el recurso aparecia como no asignado.
# Fix: assigData ahora incluye el campo "id" del recurso, y la comparacion
# se hace por ID (assignedIds.has(id)) — exacto e inmune a variaciones de nombre.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix sin asignar por ID" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\dashboard\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\dashboard\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("assignedIds.has(id)") -and $c.Contains("id: pid")) {
    Write-Host "  OK: comparacion por ID (no por nombre)" -ForegroundColor Green
} else {
    Write-Host "  ERROR" -ForegroundColor Red
}

Write-Host ""
Write-Host "  git add src\app\dashboard\page.tsx"
Write-Host '  git commit -m "fix: sin asignar por ID no por nombre - Luis y Tarsicio correctos"'
Write-Host "  git push"
